create table wksp_dtesc.sgt_evento_activo (
    id                   number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    evento_id            number not null enable,
    tipo_activo_id       number not null enable,
    activo_id            number not null enable,
    identificador_activo varchar2(255 byte) not null enable,
    descripcion_activo   varchar2(500 byte),
    estado_vinculo       varchar2(20 byte) default 'ACTIVO' not null enable,
    orden_atencion       number default 1 not null enable,
    es_principal         number(1, 0) default 0 not null enable,
    creado_por           varchar2(255 byte),
    creado_el            timestamp(6) default systimestamp,
    actualizado_por      varchar2(255 byte),
    actualizado_el       timestamp(6)
);

alter table wksp_dtesc.sgt_evento_activo
    add constraint chk_sgt_evento_activo_estado
        check ( estado_vinculo in ( 'ACTIVO', 'INACTIVO' ) ) enable;

alter table wksp_dtesc.sgt_evento_activo
    add constraint chk_sgt_evento_activo_principal
        check ( es_principal in ( 0, 1 ) ) enable;

alter table wksp_dtesc.sgt_evento_activo
    add constraint pk_sgt_evento_activo primary key ( id )
        using index enable;

alter table wksp_dtesc.sgt_evento_activo
    add constraint uq_sgt_evento_activo_unico
        unique ( evento_id,
                 tipo_activo_id,
                 activo_id )
            using index enable;


